package com.yeyamo_mobile.api.payment_service.infrastructure.outbox;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import java.util.concurrent.CompletableFuture;import org.junit.jupiter.api.Test;import org.springframework.kafka.core.KafkaTemplate;
class PaymentOutboxPublisherTests{@Test void marksPublishedAfterBrokerAcknowledgement(){PaymentOutboxRepository repository=mock(PaymentOutboxRepository.class);KafkaTemplate<String,String> kafka=mockKafka();var event=new PaymentOutboxEvent();event.id=UUID.randomUUID();event.aggregateId="payment-1";event.targetTopic="payment.events";event.payload="{}";event.occurredAt=Instant.now();when(repository.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc()).thenReturn(List.of(event));when(kafka.send("payment.events","payment-1","{}")).thenReturn(CompletableFuture.completedFuture(null));new PaymentOutboxPublisher(repository,kafka).publish();assertNotNull(event.publishedAt);verify(repository).save(event);}@SuppressWarnings("unchecked")private KafkaTemplate<String,String>mockKafka(){return mock(KafkaTemplate.class);}}
